# Simple connected component count - just use a basic flood fill
from collections import deque

def count_components(grid, val):
    h, w = len(grid), len(grid[0])
    visited = set()
    count = 0

    for r in range(h):
        for c in range(w):
            if grid[r][c] == val and (r,c) not in visited:
                # BFS to mark all connected cells
                q = deque([(r,c)])
                visited.add((r,c))
                while q:
                    cr, cc = q.popleft()
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:  # 4-connectivity
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == val and (nr,nc) not in visited:
                            visited.add((nr,nc))
                            q.append((nr,nc))
                count += 1
    return count

