def get_line_length(grid, val):
    """How long is the line for this value? Number of contiguous cells."""
    positions = [(r,c) for r in range(len(grid)) for c in range(len(grid[0])) 
                 if grid[r][c] == val]
    if not positions:
        return 0
    # Find longest horizontal contiguous segment
    max_len = 1
    current_pos_r, current_c = -1, -1
    current_len = 0

    for r, c in sorted(positions, key=lambda p: (p[0], p[1])):
        if r != current_pos_r or c != current_c + 1:
            if current_len > max_len:
                max_len = current_len
            current_len = 1
            current_pos_r, current_c = r, c
        else:
            current_len += 1
            current_c = c
    return max_len

